cat > resources/book.query.ts <<'EOF'
export default function query(ctx: QueryContext): Sql {
  return ctx.sql`
    SELECT b.id, b.title, a.name AS author, b.published
    FROM book b
    LEFT JOIN author a ON a.id = b.author_id
    WHERE b.published`;
}
EOF
cat > resources/book.command.ts <<'EOF'
function hasName(ctx, authorId) {
  const [author] = ctx.db.query(ctx.sql`SELECT name FROM author WHERE id = ${authorId}`);
  if (!author) {
    ctx.reject({ message: `author ${authorId} does not exist`, pointer: "/author_id", hint: "Create the author first with POST /authors.", status: 422 });
  }
  return author.name !== null && author.name.trim() !== "";
}

export function create(input, ctx) {
  const published = input.published === true;
  if (published && !hasName(ctx, input.author_id)) {
    ctx.reject({ message: "a book whose author has no name cannot be published", pointer: "/published", hint: "Give the author a name, or create the book unpublished.", status: 422 });
  }
  if (!published) {
    hasName(ctx, input.author_id);
  }
  const [row] = ctx.db.query(ctx.sql`INSERT INTO book (title, author_id, published) VALUES (${input.title}, ${input.author_id}, ${published}) RETURNING id`);
  return row.id;
}

export function update(input, ctx) {
  const [book] = ctx.db.query(ctx.sql`SELECT author_id, published FROM book WHERE id = ${ctx.id}`);
  const authorId = input.author_id !== undefined ? input.author_id : book.author_id;
  const published = input.published !== undefined ? input.published : book.published;
  if (published && (input.published !== undefined || input.author_id !== undefined)) {
    if (!hasName(ctx, authorId)) {
      ctx.reject({ message: "a book whose author has no name cannot be published", pointer: "/author_id", hint: "Give the author a name, or unpublish the book.", status: 422 });
    }
  }
  if (input.title !== undefined) ctx.db.exec(ctx.sql`UPDATE book SET title = ${input.title} WHERE id = ${ctx.id}`);
  if (input.author_id !== undefined) ctx.db.exec(ctx.sql`UPDATE book SET author_id = ${input.author_id} WHERE id = ${ctx.id}`);
  if (input.published !== undefined) ctx.db.exec(ctx.sql`UPDATE book SET published = ${input.published} WHERE id = ${ctx.id}`);
}

export function remove(input, ctx) {
  ctx.db.exec(ctx.sql`DELETE FROM book WHERE id = ${ctx.id}`);
}
EOF
